584	        <button type="button" className="btn btn--ghost btn--sm" onClick={() => onDone(null)}>취소</button>
585	      </div>
586	    </form>
587	  );
588	}
589	
590	function ImageForm({ onDone }: { onDone: (row: InputRow | null) => void }) {
591	  const [title, setTitle] = useState('');
592	  const [url, setUrl] = useState('');
593	  const [err, setErr] = useState<string | null>(null);
594	  const [busy, setBusy] = useState(false);
595	  const fileRef = useRef<HTMLInputElement>(null);
596	
597	  async function submit(e: FormEvent) {
598	    e.preventDefault();
599	    const file = fileRef.current?.files?.[0];
600	    if (!file && !url.trim()) return setErr('파일을 고르거나 이미지 주소를 넣어 주세요.');
601	    if (file && file.size > MAX_UPLOAD) return setErr('이미지는 5MB 이하만 올릴 수 있어요.');
602	    // file.type can be empty or odd for a valid image, so the server's magic-byte check decides; SVG is refused early.
603	    if (file && (file.type === 'image/svg+xml' || /\.svgz?$/i.test(file.name))) return setErr('PNG, JPG, WEBP, GIF 이미지만 올릴 수 있어요.');
604	    if (!file && !/^https:\/\//i.test(url.trim())) return setErr('https:// 로 시작하는 주소를 넣어 주세요.');
605	    setBusy(true);
606	    setErr(null);
607	    try {
608	      let r: { input: InputRow };
609	      if (file) {
610	        const form = new FormData();
611	        form.set('file', file);
612	        form.set('title', title);
613	        r = await api('/api/inputs', { method: 'POST', body: form });
614	      } else r = await api('/api/inputs', json('POST', { kind: 'image', title: title || '참고 이미지', url: url.trim() }));
615	      onDone(r.input);
616	    } catch (e2) {
617	      setErr((e2 as Error).message);
618	      setBusy(false);
619	    }
620	  }
621	
622	  return (
623	    <form className="add-form" onSubmit={submit} aria-label="이미지 추가">
624	      <div className="field">
625	        <label className="field__label" htmlFor="img-title">캡션</label>
626	        <input className="input" id="img-title" value={title} maxLength={200} onChange={(e) => setTitle(e.target.value)} placeholder="예: 보스방 조명 레퍼런스" />
627	      </div>
628	      <div className="field">
629	        <label className="field__label" htmlFor="img-file">이미지 파일</label>
630	        <input className="input input--file" id="img-file" type="file" ref={fileRef} accept="image/png,image/jpeg,image/webp,image/gif" aria-describedby="img-file-help" />
631	        <p className="field__help" id="img-file-help">png, jpg, webp, gif 중 하나, 5MB 이하</p>
632	      </div>
633	      <div className="field">
634	        <label className="field__label" htmlFor="img-url">또는 이미지 주소</label>
635	        <input className="input" id="img-url" type="url" inputMode="url" value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://picsum.photos/seed/cave/640/400" aria-invalid={!!err} aria-describedby="img-err" />
636	      </div>
637	      <p className="field__error" id="img-err" role="alert">{err}</p>
638	      <div className="btn-row">
639	        <button type="submit" className="btn" disabled={busy} aria-busy={busy}>이미지 추가</button>
640	        <button type="button" className="btn btn--ghost" onClick={() => onDone(null)}>닫기</button>
641	      </div>
642	    </form>
643	  );
644	}
