const B='http://localhost:3103';
const j=async(p,o)=>{const r=await fetch(B+p,o);const t=await r.text();let d;try{d=JSON.parse(t)}catch{d=t.slice(0,200)};return [r.status,d]};
const J=(m,b)=>({method:m,headers:{'content-type':'application/json'},body:typeof b==='string'?b:JSON.stringify(b)});
