// bad inputs
for (const b of [null,'notjson',{kind:'x',title:'a'},{kind:'decision',title:''},{kind:'decision',title:'a'.repeat(201),body:''},{kind:'decision',title:'a',body:5},{kind:'image',title:'a',url:'http://x.com/a.png'},{kind:'image',title:'a',url:'javascript:alert(1)'},{kind:'image',title:'a',url:'https://u:p@x.com/a.png'},[1,2],{kind:'decision',title:{}}]) { [s,d]=await j('/api/inputs',J('POST',b===null?'null':typeof b==='string'?b:b)); console.log('bad POST',JSON.stringify(b)?.slice(0,60),s,d.error); }
[s,d]=await j('/api/inputs/nope',J('PATCH',{title:'x'})); console.log('patch missing',s);
[s,d]=await j('/api/inputs/'+dec,J('PATCH','garbage')); console.log('patch garbage',s,d.error);
