[s,d]=await j('/api/inputs',J('POST',{kind:'image',title:'원격 [굴] (참고)',url:'https://picsum.photos/seed/cave/640/400'})); console.log('add url img',s,d.input?.url); const urlImg=d.input.id;
// uploads
const png=Buffer.concat([Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]),Buffer.alloc(100)]);
const up=async(buf,name,type,title)=>{const f=new FormData();f.set('file',new Blob([buf],{type}),name);if(title)f.set('title',title);return j('/api/inputs',{method:'POST',body:f})};
[s,d]=await up(png,'cap.png','image/png','업로드 캡션'); console.log('upload png',s,d.input?.url); const upImg=d.input?.id;
[s,d]=await up(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>'),'x.svg','image/svg+xml'); console.log('upload svg',s,d.error);
[s,d]=await up(Buffer.from('<svg/>'),'x.png','image/png'); console.log('upload svg-as-png',s,d.error);
[s,d]=await up(Buffer.concat([png,Buffer.alloc(5*1024*1024)]),'big.png','image/png'); console.log('upload oversize',s,d.error);
[s,d]=await up(Buffer.concat([Buffer.from('GIF89a'),Buffer.alloc(20)]),'g.gif','image/gif'); console.log('upload gif',s,d.input?.title);
const gif=d.input.id;
[s,d]=await up(Buffer.alloc(0),'e.png','image/png'); console.log('upload empty',s,d.error);
// image serve
