[s,d]=await j('/api/generate',J('POST',{decisionIds:decIds,imageIds:imgIds})); console.log('generate',s,d.doc?.title,d.doc?.provider,d.error);
const md=d.doc.markdown; const docId=d.doc.id;
const imgs=all.filter(i=>imgIds.includes(i.id)); for (const i of imgs) console.log(' embedded?',i.url, md.includes('('+i.url.replace(/[\s()<>]/g,c=>encodeURIComponent(c))+')'));
console.log(md.split('\n').filter(l=>/^#/.test(l)).join(' / '));
console.log(md.split('\n').filter(l=>l.startsWith('|')).join('\n'));
console.log(md.slice(md.indexOf('## 아트'), md.indexOf('## 결정 로그')));
for (const b of [{},{decisionIds:[],imageIds:[]},{decisionIds:'x',imageIds:[]},{decisionIds:['nope'],imageIds:[]},{decisionIds:[1],imageIds:[]},{decisionIds:Array(201).fill('a'),imageIds:[]}]) {[s,d]=await j('/api/generate',J('POST',b)); console.log('bad gen',JSON.stringify(b).slice(0,50),s,d.error)}
[s,d]=await j('/api/generate',J('POST','xx')); console.log('bad gen nonjson',s,d.error);
// save/reopen
[s,d]=await j('/api/docs/'+docId,J('PATCH',{markdown:'# 바뀐 제목 기획서\n\n본문 수정\n\n![a](/samples/ui.svg)'})); console.log('patch doc',s,d.doc?.title);
[s,d]=await j('/api/docs/'+docId); console.log('reopen',s,d.doc?.markdown.slice(0,30));
[s,d]=await j('/api/docs'); console.log('docs list',s,d.docs.length,d.docs[0].id===docId,d.docs[0].title);
[s,d]=await j('/api/docs/nope'); console.log('doc missing',s);
[s,d]=await j('/api/docs/'+docId,J('PATCH',{markdown:5})); console.log('patch doc bad',s);
[s,d]=await j('/api/docs/'+docId,J('PATCH',{markdown:'x'.repeat(200001)})); console.log('patch doc huge',s);
// delete
[s,d]=await j('/api/inputs/'+dec,{method:'DELETE'}); console.log('del dec',s,JSON.stringify(d));
[s,d]=await j('/api/inputs/'+dec,{method:'DELETE'}); console.log('del again',s);
[s,d]=await j('/api/inputs/'+gif,{method:'DELETE'}); console.log('del unused upload',s,JSON.stringify(d));
r=await fetch(B+'/api/images/'+gif); console.log('serve after del',r.status);
console.log(JSON.stringify({dec,urlImg,upImg,docId}));
EOF
