320:.gallery__bar .seg, .gallery__bar .btn-row { margin-left: auto; }
321:.gallery__track { display: grid; gap: var(--space-sm); margin: 0; padding: 0; list-style: none; }
322:.gallery__track[data-view="grid"] { grid-template-columns: repeat(3, minmax(0, 1fr)); }
323:@container (max-width: 420px) { .gallery__track[data-view="grid"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
324:.gallery__track[data-view="slide"] { grid-auto-flow: column; grid-auto-columns: minmax(0, 78%); overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scrollbar-width: thin; padding-bottom: var(--space-2xs); }
325:.gallery__track[data-view="slide"] > li { scroll-snap-align: start; }
337:.md-doc { max-width: 72ch; color: var(--color-ink); font-size: var(--text-md); line-height: 1.75; }
338:.md-doc > * + * { margin-top: var(--space-md); }
339:.md-doc h1 { font-size: var(--text-3xl); line-height: 1.25; }
340:.md-doc h2 { margin-top: var(--space-xl); padding-bottom: var(--space-xs); border-bottom: var(--rule-hair) solid var(--color-rule); font-size: var(--text-xl); }
341:.md-doc h3 { margin-top: var(--space-lg); font-size: var(--text-lg); }
342:.md-doc h4 { margin-top: var(--space-lg); font-size: var(--text-md); }
343:.md-doc h2 + *, .md-doc h3 + *, .md-doc h4 + * { margin-top: var(--space-sm); }
344:.md-doc ul, .md-doc ol { padding-left: var(--space-lg); }
345:.md-doc li + li { margin-top: var(--space-2xs); }
346:.md-doc li::marker { color: var(--color-muted); }
347:.md-doc a { color: var(--color-accent-text); }
348:.md-doc strong { font-weight: 600; }
349:.md-doc blockquote { margin-inline: 0; padding: var(--space-2xs) var(--space-md); border-left: 2px solid var(--color-rule-2); color: var(--color-ink-2); }
350:.md-doc code { padding: var(--space-3xs) var(--space-2xs); border-radius: var(--radius-mark); background: var(--color-paper-3); font-size: 0.875em; }
351:.md-doc pre { overflow-x: auto; padding: var(--space-md); border-radius: var(--radius-inner); background: var(--color-graphite); color: var(--color-graphite-ink); font-size: var(--text-sm); line-height: 1.6; }
352:.md-doc pre code { padding: 0; background: none; font-size: inherit; color: inherit; }
